def check_ref_format(scm: "Git", ref: ExpRefInfo):
    # Check for invalid characters in experiment name
    # Based on Git reference name rules: https://git-scm.com/docs/git-check-ref-format
    invalid_chars = ['~', '^', ':', '\\', '?', '*', '[', ' ', '\t', '\n', '\r']

    for char in invalid_chars:
        if char in ref.name:
            raise InvalidArgumentError(
                f"Invalid experiment name '{ref.name}'. Names cannot contain '{char}'. "
                "Experiment names must follow rules in "
                "https://git-scm.com/docs/git-check-ref-format"
            )

    # Check for slash which is handled separately
    if "/" in ref.name:
        raise InvalidArgumentError(
            f"Invalid experiment name '{ref.name}'. Names cannot contain '/'. "
            "Experiment names must follow rules in "
            "https://git-scm.com/docs/git-check-ref-format"
        )

    # Also check the full reference format using Git's check_ref_format
    if not scm.check_ref_format(str(ref)):
        raise InvalidArgumentError(
            f"Invalid experiment name '{ref.name}'. "
            "Experiment names must follow rules in "
            "https://git-scm.com/docs/git-check-ref-format"
        )

